package bo.com.ganadero.alertas.infrastructure;import bo.com.ganadero.alertas.domain.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;import java.sql.*;import java.time.Instant;import java.time.OffsetDateTime;import java.util.*;
@Repository public class JdbcSuscripcionPushRepository implements SuscripcionPushRepository{private final JdbcClient j;public JdbcSuscripcionPushRepository(JdbcClient j){this.j=j;}public SuscripcionPush guardar(SuscripcionPush s){UUID id=j.sql("insert into alertas.suscripciones_push(id,empresa_id,usuario_id,endpoint,p256dh,auth,dispositivo_nombre,user_agent,activo,ultimo_uso_at) values(:id,:e,:u,:ep,:p,:a,:d,:ua,true,now()) on conflict(usuario_id,endpoint) do update set empresa_id=excluded.empresa_id,p256dh=excluded.p256dh,auth=excluded.auth,dispositivo_nombre=excluded.dispositivo_nombre,user_agent=excluded.user_agent,activo=true,ultimo_uso_at=now(),updated_at=now() returning id").param("id",s.id()).param("e",s.empresaId()).param("u",s.usuarioId()).param("ep",s.endpoint()).param("p",s.p256dh()).param("a",s.auth()).param("d",s.dispositivoNombre()).param("ua",s.userAgent()).query(UUID.class).single();return listar(s.empresaId(),s.usuarioId()).stream().filter(x->x.id().equals(id)).findFirst().orElseThrow();}public List<SuscripcionPush>listar(UUID e,UUID u){return j.sql("select * from alertas.suscripciones_push where empresa_id=:e and usuario_id=:u and activo order by ultimo_uso_at desc nulls last").param("e",e).param("u",u).query(this::map).list();}public List<SuscripcionPush>listarActivas(UUID e){return j.sql("select * from alertas.suscripciones_push where empresa_id=:e and activo order by ultimo_uso_at desc nulls last").param("e",e).query(this::map).list();}public void desactivar(UUID id,UUID e,UUID u){j.sql("update alertas.suscripciones_push set activo=false,updated_at=now() where id=:id and empresa_id=:e and usuario_id=:u").param("id",id).param("e",e).param("u",u).update();}public void desactivarTodas(UUID id,UUID e){j.sql("update alertas.suscripciones_push set activo=false,updated_at=now() where id=:id and empresa_id=:e").param("id",id).param("e",e).update();}public PreferenciasNotificacion preferencias(UUID e,UUID u){return j.sql("select * from alertas.preferencias_notificacion where empresa_id=:e and usuario_id=:u").param("e",e).param("u",u).query(this::pref).optional().orElse(new PreferenciasNotificacion(e,u,true,true,true,true,true,true,true,true));}public PreferenciasNotificacion guardarPreferencias(PreferenciasNotificacion p){j.sql("insert into alertas.preferencias_notificacion values(:e,:u,:r,:s,:t,:p,:c,:cr,:ur,:re,now()) on conflict(empresa_id,usuario_id) do update set reproduccion=excluded.reproduccion,sanidad=excluded.sanidad,tratamientos=excluded.tratamientos,pesajes=excluded.pesajes,casos_criticos=excluded.casos_criticos,criticas=excluded.criticas,urgentes=excluded.urgentes,recordatorios=excluded.recordatorios,updated_at=now()").param("e",p.empresaId()).param("u",p.usuarioId()).param("r",p.reproduccion()).param("s",p.sanidad()).param("t",p.tratamientos()).param("p",p.pesajes()).param("c",p.casosCriticos()).param("cr",p.criticas()).param("ur",p.urgentes()).param("re",p.recordatorios()).update();return p;}private SuscripcionPush map(ResultSet r,int n)throws SQLException{return new SuscripcionPush(r.getObject("id",UUID.class),r.getObject("empresa_id",UUID.class),r.getObject("usuario_id",UUID.class),r.getString("endpoint"),r.getString("p256dh"),r.getString("auth"),r.getString("dispositivo_nombre"),r.getString("user_agent"),r.getBoolean("activo"),instant(r,"created_at"),instant(r,"updated_at"),instant(r,"ultimo_uso_at"));}private PreferenciasNotificacion pref(ResultSet r,int n)throws SQLException{return new PreferenciasNotificacion(r.getObject("empresa_id",UUID.class),r.getObject("usuario_id",UUID.class),r.getBoolean("reproduccion"),r.getBoolean("sanidad"),r.getBoolean("tratamientos"),r.getBoolean("pesajes"),r.getBoolean("casos_criticos"),r.getBoolean("criticas"),r.getBoolean("urgentes"),r.getBoolean("recordatorios"));}private static Instant instant(ResultSet r,String c)throws SQLException{OffsetDateTime v=r.getObject(c,OffsetDateTime.class);return v==null?null:v.toInstant();}
}